
const menuToggle=document.getElementById("menu-toggle"),navigation=document.getElementById("navigation");if(menuToggle&&navigation){function setMenuOpen(isOpen){navigation.classList.toggle("active",isOpen);menuToggle.setAttribute("aria-expanded",String(isOpen));menuToggle.setAttribute("aria-label",isOpen?"Close navigation menu":"Open navigation menu")}menuToggle.addEventListener("click",()=>{setMenuOpen(menuToggle.getAttribute("aria-expanded")!=="true")});navigation.addEventListener("click",event=>{if(event.target.closest("a"))setMenuOpen(false)});document.addEventListener("keydown",event=>{if(event.key==="Escape"&&menuToggle.getAttribute("aria-expanded")==="true"){setMenuOpen(false);menuToggle.focus()}});window.matchMedia("(min-width: 701px)").addEventListener("change",event=>{if(event.matches)setMenuOpen(false)})}
